        source.body.innerHTML = '<a href=\"https://example.com\" class=\"link\" style=\"color: red\">Original</a><img src=\"https://example.com/a.png\" class=\"picture\" style=\"width: 10px\">';
        replaceURLs(source, 'uid', 'first-message');

