        expect(preview.querySelectorAll('a, img')).toHaveLength(0);
        expect(preview.body.textContent).toContain('Original');
        expect(preview.body.textContent).toContain('Invented');

        restoreURLs(source, 'first-message');
        expect(source.querySelector('a')?.getAttribute('href')).toBe('https://example.com');
        expect(source.querySelector('a')?.getAttribute('class')).toBe('link');
        expect(source.querySelector('a')?.getAttribute('style')).toBe('color: red');
